        "questionEn": "Hooke's law is valid strictly up to which threshold on the stress-strain curve?",
        "questionTa": "தகைவு-திரிபு வரைபடத்தில் ஹூக் விதி எந்த எல்லை வரை மட்டுமே துல்லியமாகப் பொருந்தும்?",
