        "questionEn": "A closed organ pipe and an open organ pipe have the same length. The ratio of their fundamental frequencies is:",
        "questionTa": "சம நீளமுள்ள ஒரு மூடிய குழாய் மற்றும் திறந்த குழாயின் அடிப்படை அதிர்வெண்களின் விகிதம்:",
